/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen2Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffsetMillis = (5 * 60 + 30) * 1000;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset_PositiveMinutes() {
        // -5:30 represented as hoursOffset = -5, minutesOffset = 30
        // Logic: hoursInMinutes = -300. Since < 0, minutesOffset = -300 + (-30) = -330? 
        // Wait, looking at the code: minutesOffset = FieldUtils.safeAdd(hoursInMinutes, -minutesOffset);
        // If hoursOffset = -5, minutesOffset = 30:
        // hoursInMinutes = -300. 
        // minutesOffset = -300 + (-30) = -330.
        // offset = -330 * 60000 = -19800000
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedOffsetMillis = ((-5 * 60) - 30) * 1000;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset_ZeroMinutes() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-1, 0);
        int expectedOffsetMillis = -1 * 60 * 60 * 1000;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        DateTimeZone.forOffsetHoursMinutes(1, -1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(1, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_ArithmeticOverflow() {
        // Attempt to trigger ArithmeticException in FieldUtils.safeMultiply or safeAdd
        // Using Integer.MAX_VALUE to force overflow in hoursInMinutes or offset calculation
        DateTimeZone.forOffsetHoursMinutes(Integer.MAX_VALUE, 30);
    }

    @Test
    public void testForOffsetHoursMinutes_LargeNegativeOffset() {
        // Testing the branch where hoursInMinutes < 0
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-12, 45);
        int expectedOffsetMillis = ((-12 * 60) - 45) * 60 * 1000;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryMinutes() {
        // Test 59 minutes
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 59);
        int expectedOffsetMillis = 59 * 60 * 1000;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }
}
